import { useEffect, useMemo, useState } from "react";
import { useLocation, useNavigate, useParams, useSearchParams } from "react-router-dom";
import { isDatasetId, type DatasetId } from "../../entities/dataset";
import { isDatasetVersionId, type DatasetVersionId } from "../../entities/dataset-version";
import { isEpisodeId, type EpisodeId } from "../../entities/episode";
import { EpisodeWorkbenchCore, createPlaybackClock, type StreamDescriptor, type ViewerStreamModality } from "../../features/viewer";
import { routes as cleaningRoutes } from "../../features/cleaning/routing";
import { useViewerEpisodeQuery } from "../../features/datasets/api";
import { RegionState } from "../../features/datasets/components/RegionState";
import { datasetRegionStateForError } from "../../features/datasets/components/error-state";
import { routes } from "../../features/datasets/routing";
import { useCapabilities } from "../../shared/auth/use-capabilities";
import { assetEpisodeViewerQueryCodec } from "./query-codec";
import "../../features/datasets/components/datasets.css";

const invalidDataset = "dataset_invalid" as DatasetId;
const invalidVersion = "version_invalid" as DatasetVersionId;
const invalidEpisode = "episode_invalid" as EpisodeId;

function modality(kind: string): ViewerStreamModality {
  const normalized = kind.toLowerCase();
  if (normalized.includes("video") || normalized.includes("rgb")) return "rgb";
  if (normalized.includes("depth")) return "depth";
  if (normalized.includes("point")) return "pointcloud";
  if (normalized.includes("joint")) return "joint_state";
  if (normalized.includes("action")) return "action";
  if (normalized.includes("force")) return "force";
  if (normalized.includes("pose")) return "pose";
  if (normalized.includes("imu")) return "imu";
  return "other";
}

export function EpisodeViewerShell() {
  const raw = useParams();
  const navigate = useNavigate();
  const location = useLocation();
  const [params] = useSearchParams();
  const search = assetEpisodeViewerQueryCodec.parse(params);
  const capabilities = useCapabilities();
  const valid = isDatasetId(raw.datasetId) && isDatasetVersionId(raw.versionId) && isEpisodeId(raw.episodeId);
  const datasetId = valid ? raw.datasetId as DatasetId : invalidDataset;
  const versionId = valid ? raw.versionId as DatasetVersionId : invalidVersion;
  const episodeId = valid ? raw.episodeId as EpisodeId : invalidEpisode;
  const query = useViewerEpisodeQuery(datasetId, versionId, episodeId, valid && capabilities.has("episode.read"));
  const [selection, setSelection] = useState<{ start: string; end: string } | null>(() => search.selectionStartNs && search.selectionEndNs ? { start: search.selectionStartNs, end: search.selectionEndNs } : null);

  const revision = query.data?.revision;
  const startNs = revision?.started_at_ns ?? "0";
  const endNs = revision ? (BigInt(revision.started_at_ns) + BigInt(revision.duration_ns)).toString() : "1";
  const clock = useMemo(() => createPlaybackClock({ startNs, endNs: BigInt(endNs) > BigInt(startNs) ? endNs : (BigInt(startNs) + 1n).toString() }), [endNs, startNs]);
  useEffect(() => () => clock.dispose(), [clock]);
  useEffect(() => { if (search.t && /^\d+$/.test(search.t)) clock.seek(search.t); }, [clock, search.t]);

  const streams = useMemo<readonly StreamDescriptor[]>(() => (revision?.streams ?? []).map((stream) => ({
    id: stream.episode_stream_id,
    canonicalPath: stream.channel_path,
    displayName: stream.channel_path,
    modality: modality(stream.kind),
    schema: { id: `hc.${stream.kind.toLowerCase()}`, version: "contract-v1" },
    startNs: stream.t_start_ns,
    endNs: stream.t_end_ns,
    availability: "unsupported",
  })), [revision]);

  if (!valid) return <main className="dataset-page" data-page-id="P06-viewer"><RegionState state="not-found" message="URL 中的 Dataset、Version 或 Episode 稳定 ID 无效。" /></main>;
  if (capabilities.loading) return <main className="dataset-page"><RegionState state="first-loading" /></main>;
  if (capabilities.failed || !capabilities.has("episode.read")) return <main className="dataset-page"><RegionState state="forbidden" message="只读 Viewer 需要 episode.read。" /></main>;
  if (query.isPending) return <main className="dataset-page"><RegionState state="first-loading" /></main>;
  if (query.isError) return <main className="dataset-page"><RegionState state={datasetRegionStateForError(query.error)} message={query.error instanceof Error ? query.error.message : undefined} onRetry={() => void query.refetch()} /></main>;

  const fallback = routes.datasetDetail.build({ datasetId, tab: "episodes" });
  const returnTo = search.returnTo ?? fallback;
  const viewerReturn = `${location.pathname}${location.search}`;
  return (
    <main className="dataset-page" data-page-id="P06-viewer" data-navigation-owner-page-id="P06">
      <header className="dataset-resource-header"><div><p className="dataset-eyebrow">Readonly episode viewer</p><h1>Episode {episodeId}</h1><p><code>{datasetId}</code> · <code>{versionId}</code> · Revision <code>{revision!.revision_id}</code></p></div><div className="dataset-actions"><button type="button" className="dataset-button dataset-button--secondary" onClick={() => navigate(returnTo)}>返回</button></div></header>
      <section className="dataset-workbench-shell">
        <aside className="dataset-workbench-rail"><h2>Streams</h2>{streams.map((stream) => <div key={stream.id}><strong>{stream.displayName}</strong><small>{stream.id}</small></div>)}</aside>
        <div className="dataset-workbench-core"><EpisodeWorkbenchCore episodeId={episodeId} datasetId={datasetId} versionId={versionId} clock={clock} streams={streams} mode="readonly" onTimeRangeSelect={(start, end) => setSelection({ start, end })} /></div>
        <aside className="dataset-workbench-inspector"><h2>交接</h2><p>Viewer 保持只读，时间范围采用 [start, end)。</p>{selection ? <p><code>{selection.start}</code><br />—<br /><code>{selection.end}</code></p> : <p>在时间轴拖动选择范围。</p>}
          <button type="button" className="dataset-button" disabled title="P08 尚未导出稳定 annotation route builder">标注入口不可用</button>
          <button type="button" className="dataset-button dataset-button--secondary" disabled={!capabilities.has("manual_issue.create")} onClick={() => navigate(cleaningRoutes.manualIssues.build({ datasetId, versionId, episodeId, returnTo: viewerReturn }))}>创建 ManualIssue</button>
          <button type="button" className="dataset-button dataset-button--secondary" disabled={!capabilities.has("dataset_version.download_raw")}>下载原始数据</button>
          {!capabilities.has("manual_issue.create") ? <RegionState state="feature-unavailable" message="ManualIssue 创建需要独立 capability；不会创建 CleaningDraft，也不会直达 P11。" /> : null}
        </aside>
      </section>
    </main>
  );
}

export default EpisodeViewerShell;
